#!/usr/bin/perl
use strict;
use warnings;

# Read the regex pattern
open my $fh, '<', '/app/regex.txt' or die "Cannot open regex.txt: $!";
my $pattern = do { local $/; <$fh> };
close $fh;
chomp $pattern;

my @test_cases = (
    ["Error at 192.168.1.1 on 2023-01-15", ["2023-01-15"]],
    ["Error at 192.168.1.1 on 2023-01-15 and 2023-02-14", ["2023-02-14"]],
    ["192.168.1.1 logged 2023-03-01 then 2023-04-30 event", ["2023-04-30"]],
    ["No IPv4 address with 2023-05-15 date", []],
    ["192.168.1.1 no dates here", []],
    ["10.0.0.255 2023-02-29", ["2023-02-29"]],
    ["10.0.0.1 2023-02-30", []],
    ["10.0.0.1 2023-04-31", []],
    ["10.0.0.1 2023-04-30", ["2023-04-30"]],
    ["user 1134-12-1234 with 192.168.1.1 2023-12-25", ["2023-12-25"]],
    ["0.0.0.0 2023-01-01", ["2023-01-01"]],
    ["255.255.255.255 2023-12-31", ["2023-12-31"]],
    ["192.168.01.1 2023-01-01", []],
    ["192.168.1.1a 2023-01-01", []],
    ["a192.168.1.1 2023-01-01", []],
    ["192.168.1.1 2023-01-01end", []],
    ["192.168.1.1 start2023-01-01", []],
);

my $passed = 0;
my $failed = 0;

print "Testing regex pattern...\n";

foreach my $test (@test_cases) {
    my $line = $test->[0];
    my @expected = @{$test->[1]};

    my @matches;
    if ($line =~ /$pattern/m) {
        @matches = ($1);  # Capture group 1 is the date
    }

    my $match_str = join(",", @matches);
    my $exp_str = join(",", @expected);

    if ($match_str eq $exp_str) {
        print "✓ PASS: " . substr($line, 0, 50) . "\n";
        $passed++;
    } else {
        print "✗ FAIL: " . substr($line, 0, 50) . "\n";
        print "  Expected: [$exp_str]\n";
        print "  Got:      [$match_str]\n";
        $failed++;
    }
}

print "\nResults: $passed passed, $failed failed\n";

